const MailtrainPaper=globalThis.MailtrainPaper;
// The shared engine supplies the Train's board, clocks and orthographic view.
const trainNativeOutput={canvas:paperOutputCanvas,scale:paperOutputScale};
const trainChapter=MailtrainChapter.makeOut();
const trainFrame={
 level:null,boardSource:null,traces:null,time:0,chapterMode:'',chapterFrame:0,
 stationStage:0,chapterPose:trainChapter,worldFrame:0,motion:true,grayscale:false,
 viewport:{width:0,height:0,dpr:1},insets:{top:0,right:0,bottom:0,left:0},camera:{x:0,y:0,scale:16}
};
let trainRenderer=null,trainCanvas=null,trainOutput=false;
function trainRead(){
 const f=trainFrame,demo=cpActive()&&CP.train&&CP.mode==='demo';
 gPrepareSrc();
 f.level=demo?CP.demo.level:gm.L;
 f.boardSource=gBoardSource();f.traces=f.boardSource.traces;
 f.time=demo?(CP.frame%(CP.demo.loop*60))/60:gm.t;
 f.chapterMode=cpActive()&&CP.train?CP.mode:'';
 f.chapterFrame=CP.frame;f.stationStage=TC.stage;
 MailtrainChapter.sample(f,TRAINCHAPTER,trainChapter);
 f.motion=!document.hidden&&!document.documentElement.classList.contains('reduced');
 if(f.motion)f.worldFrame=loopFrame;
 f.grayscale=grayscale;
 f.viewport.width=LW;f.viewport.height=LH;
 f.viewport.dpr=Math.max(paperRenderScale(),Math.min(4,Math.ceil(scale)));
 const floor=ROOM_LAYOUT.sortingFloor,layout=MailtrainGeometry.layout;
 f.camera.x=OX+floor.x-floor.y-(layout.boardX-layout.boardY)*16-viewX;
 f.camera.y=OY+(floor.x+floor.y)*.5-((layout.boardX+layout.boardY)*.5-3.125)*16-viewY;
}
function trainDraw(){
 trainOutput=false;
 if(!trainRenderer||!gm.L||!GAME_MODE||!G_KEEP_PROGRESS||gm.custom||paperAtlasBuilding)return false;
 trainRead();trainRenderer.prepare(trainFrame);trainRenderer.draw(trainFrame);
 trainOutput=true;return true;
}
return {
 async mount(){
  api.check();
  const assets=await MailtrainPaper.load(MailtrainAssets);api.check();
  const canvas=document.createElement('canvas');trainCanvas=canvas;
  trainRenderer=MailtrainPaper.create({canvas,assets,BOARDANIM});
  paperOutputCanvas=()=>trainOutput?canvas:trainNativeOutput.canvas();
  paperOutputScale=()=>trainOutput?trainFrame.viewport.dpr:trainNativeOutput.scale();
  api.hooks({render:trainDraw,smooth:true,stationOutput:true});
  dirty=true;
 },
 refresh(){api.check();dirty=true;},
 dispose(){
  trainOutput=false;trainRenderer?.dispose();trainRenderer=null;
  trainFrame.level=trainFrame.boardSource=trainFrame.traces=null;
  if(trainCanvas)trainCanvas.width=trainCanvas.height=1;
  trainCanvas=null;
 },
 resources(){
  const info=trainRenderer?.resources();
  return info?{...info,bytes:info.textureBytes+info.surfacePixels*4}: {bytes:0};
 }
};
